using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Configure an OpenAI key via the AI:ApiKey setting or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddChatClient(b => b
    .UseFunctionInvocation()
    .Use(new OpenAIClient(apiKey).GetChatClient(modelId)));

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var tools = host.Services.GetRequiredService<ResearchTools>();

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

var aiTools = new AIFunction[]
{
    AIFunctionFactory.Create(tools.SearchWeb),
    AIFunctionFactory.Create(tools.SaveNote),
    AIFunctionFactory.Create(tools.GetNotes),
};

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information using multiple queries
        2. Saving important findings as notes with descriptive titles
        3. After gathering enough information, retrieving all notes and writing a comprehensive summary

        Perform at least 3 different searches to cover various aspects of the topic.
        Save key findings as notes after each search. When finished researching,
        call GetNotes to review everything, then write a well-structured final summary.
        """),
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var response = await chatClient.GetResponseAsync(messages, new ChatOptions
{
    Tools = [.. aiTools],
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

Console.WriteLine("📋 Research Summary:");
Console.WriteLine(new string('─', 60));
Console.WriteLine(response.Text);

