using System.ComponentModel;
using System.Net.Http.Json;
using System.Text;
using System.Text.Json.Serialization;
using Microsoft.Extensions.AI;

/// <summary>
/// Tools available to the research agent for searching the web and managing notes.
/// </summary>
public sealed class ResearchTools
{
    private readonly List<Note> _notes = [];
    private static readonly HttpClient HttpClient = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
        },
    };

    [Description("Search the web for information on a query. Returns a list of relevant results with titles, snippets, and URLs.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            // Use DuckDuckGo Instant Answer API (free, no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var ddg = await HttpClient.GetFromJsonAsync<DuckDuckGoResponse>(url);

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: \"{query}\"\n");

            if (!string.IsNullOrWhiteSpace(ddg?.AbstractText))
            {
                sb.AppendLine($"## Summary\n{ddg.AbstractText}");
                sb.AppendLine($"Source: {ddg.AbstractSource} ({ddg.AbstractURL})\n");
            }

            if (ddg?.RelatedTopics is { Count: > 0 })
            {
                sb.AppendLine("## Related Topics");
                foreach (var topic in ddg.RelatedTopics.Take(5))
                {
                    if (!string.IsNullOrWhiteSpace(topic.Text))
                    {
                        sb.AppendLine($"- {topic.Text}");
                        if (!string.IsNullOrWhiteSpace(topic.FirstURL))
                            sb.AppendLine($"  URL: {topic.FirstURL}");
                    }
                }
            }

            var result = sb.ToString();
            if (result.Trim().Length < 50)
                return $"No detailed results found for \"{query}\". Try a more specific or different query.";

            return result;
        }
        catch (Exception ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note. Use this to record important findings from search results.")]
    public string SaveNote(
        [Description("A short descriptive title for the note")] string title,
        [Description("The content of the note with key findings")] string content)
    {
        var note = new Note(title, content, DateTime.UtcNow);
        _notes.Add(note);
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
        return $"Note #{_notes.Count} saved: \"{title}\"";
    }

    [Description("Retrieve all saved research notes. Call this before writing the final summary to review all findings.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet. Search for information and save notes first.";

        var sb = new StringBuilder();
        sb.AppendLine($"=== Research Notes ({_notes.Count} total) ===\n");

        for (var i = 0; i < _notes.Count; i++)
        {
            var note = _notes[i];
            sb.AppendLine($"--- Note #{i + 1}: {note.Title} ---");
            sb.AppendLine(note.Content);
            sb.AppendLine();
        }

        Console.WriteLine($"  📖 Retrieved {_notes.Count} notes");
        return sb.ToString();
    }

    private sealed record Note(string Title, string Content, DateTime SavedAt);
}

internal sealed class DuckDuckGoResponse
{
    [JsonPropertyName("AbstractText")]
    public string? AbstractText { get; set; }

    [JsonPropertyName("AbstractSource")]
    public string? AbstractSource { get; set; }

    [JsonPropertyName("AbstractURL")]
    public string? AbstractURL { get; set; }

    [JsonPropertyName("RelatedTopics")]
    public List<DuckDuckGoTopic>? RelatedTopics { get; set; }
}

internal sealed class DuckDuckGoTopic
{
    [JsonPropertyName("Text")]
    public string? Text { get; set; }

    [JsonPropertyName("FirstURL")]
    public string? FirstURL { get; set; }
}

